// Renderiza o passo da régua. Janela de 24h aberta => texto livre; fechada => template aprovado (ou pula).
const out = [];
for (const it of $input.all()) {
  const j = it.json; const nome = String(j.nome || '').trim().split(' ')[0] || 'olá';
  const body = String(j.template || '').replace(/\{\{nome\}\}/g, nome).replace(/\{\{escritorio\}\}/g, j.escritorio || 'escritório');
  let template = null;
  if (!j.janela_aberta) {
    if (!j.template_name) { out.push({ json: { ...j, body, skip: true, motivo: 'janela fechada e sem template aprovado' } }); continue; }
    template = { name: j.template_name, language: { code: j.template_language || 'pt_BR' },
                 components: [{ type: 'body', parameters: [{ type: 'text', text: nome }, { type: 'text', text: j.escritorio || 'escritório' }] }] };
  }
  out.push({ json: { ...j, body, template, skip: false } });
}
return out;

