with m as (
  insert into public.messages (office_id, conversation_id, direction, sender, body, status, ai_meta, template)
  values ($1::uuid, $2::uuid, 'out', 'sistema', $3, 'pending', jsonb_build_object('agent_role', 'followup', 'step', $4::int), $6::jsonb)
  returning id
)
select m.id as message_id, public.followup_mark_sent($5::uuid) as regua from m;
